        assertEquals(165, premium(NEWCOMER, 1, List.of(item("sword", "steel", 3, true))));
    }

    @Test
    void longStandingCustomersSecondContractPays160() {
        assertEquals(160, premium(new Customer(3), 2, List.of(item("sword", "steel", 7, true))));
